use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let num = input.as_u64().unwrap() as i64;
    if num == 0 {
        return Value::from(-1);
    }
    let mut pos = 0;
    let mut n = num;
    while n & 1 == 0 {
        n >>= 1;
        pos += 1;
    }
    Value::from(pos)
}
